import{_ as o,o as t,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const d=JSON.parse('{"title":"🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-07-24.md","filePath":"science-log/src/reconstructed/2026-07-24.md"}'),a={name:"science-log/src/reconstructed/2026-07-24.md"};function s(g,r,i,l,c,h){return t(),n("div",null,[...r[0]||(r[0]=[e('<h1 id="🔬-科学快报-2026年7月24日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年7月24日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年7月24日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-07 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 检索说明：2026-07-24 为<strong>周五</strong>。CrossRef 按 <code>from-pub-date=until-pub-date=2026-07-24</code> 检索：Nature（0028-0836）命中 6 条但<strong>研究论文 0 条</strong>（5 条为 d41586 新闻/Briefing，1 条为 Author Correction，均按要求丢弃）；Science 前缀（10.1126）命中 83 条（以 Science Advances 为主）；PNAS（0027-8424）命中 9 条。故科学 5 篇取自<strong>当日真实出版</strong>的 PNAS 2 篇 + Science Advances 3 篇。AI 5 篇严格取自 arXiv <code>submittedDate:[202607240000 TO 202607242359]</code> 的 cs.AI 真实条目（命中 40 篇）。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 <code>[202607240000 TO 202607242359]</code>（cs.AI，40 条）+ CrossRef 摘要核验 ｜ 重建日：2026-11-07</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧲-弱到测不到的「倾斜磁矩」-被太赫兹辐射直接读出来" tabindex="-1">🧲 弱到测不到的「倾斜磁矩」，被太赫兹辐射直接读出来 <a class="header-anchor" href="#🧲-弱到测不到的「倾斜磁矩」-被太赫兹辐射直接读出来" aria-label="Permalink to &quot;🧲 弱到测不到的「倾斜磁矩」，被太赫兹辐射直接读出来&quot;">​</a></h3><p><strong>Resolving weak moments in canted antiferromagnets via time-domain terahertz emission spectroscopy</strong><em>PNAS（2026）</em></p><p>倾斜反铁磁体（canted antiferromagnet）身上有个尴尬的组合：反铁磁序带来太赫兹级的超快响应，而自旋倾斜带来的净磁矩小到常规磁光与电学手段在薄膜里几乎测不出来。作者（Sha、Guan、Wang、Li 等 12 人）改用<strong>时域太赫兹发射光谱</strong>做非接触探针，模型体系是外延 TmFeO₃/Pt 异质结。结果很干净：发射的太赫兹信号<strong>直接跟随倾斜的 Fe³⁺ 净磁矩取向</strong>，因此可以实时追踪该磁矩在自旋重取向转变（spin reorientation transition）中的连续转动。更反常的是，该体系的太赫兹磁滞<strong>极性与常规铁磁体/Pt 体系相反</strong>，指向一种非常规的界面磁构型。这把太赫兹发射确立为解析倾斜反铁磁薄膜、超薄膜超快磁响应的实用工具——也就是给&quot;几乎无净磁矩&quot;的反铁磁自旋电子学提供了一台可用的读表。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2603194123" target="_blank" rel="noreferrer">10.1073/pnas.2603194123</a></p><h3 id="☁️-7000-次高分辨率模拟-太平洋低云把变暖又放大了一档" tabindex="-1">☁️ 7000 次高分辨率模拟：太平洋低云把变暖又放大了一档 <a class="header-anchor" href="#☁️-7000-次高分辨率模拟-太平洋低云把变暖又放大了一档" aria-label="Permalink to &quot;☁️ 7000 次高分辨率模拟：太平洋低云把变暖又放大了一档&quot;">​</a></h3><p><strong>High-resolution simulations reveal positive global warming feedback from Pacific low clouds</strong><em>Science Advances（2026）</em></p><p>海洋低云反馈是气候预估里最大的不确定源之一，因为云的量与亮度对边界层结构极为敏感，而粗网格模式参数化不了。作者（Chammas、Wang、Schneider、Carver、Shen、Parker 等 10 人）做了 <strong>7,083 次热带太平洋低云的高分辨率模拟</strong>，把「海表增温」与「CO₂ 直接效应」两个因素拆开。结果是：仅海表增温就给出 <strong>+0.14 W m⁻² K⁻¹ 的正低云反馈</strong>，翻倍 CO₂ 时基本不变；但到 <strong>四倍 CO₂</strong> 时，总云辐射响应跃升到 <strong>+0.43 W m⁻² K⁻¹</strong>，暴露出强非线性。机制是：增温通过逆温层增强与下沉减弱抬高了云中含水量（增亮），同时云量下降；而高 CO₂ 的快速调整抵消了这层「保护性增厚」，于是云量减少不再被亮度增加抵消。结论直接冲击「气候敏感度是常数」的默认假设——它更依赖气候状态本身。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aec8488" target="_blank" rel="noreferrer">10.1126/sciadv.aec8488</a></p><h3 id="🧫-胶质细胞的线粒体撑不住-死的是神经元-vamp7-与「接触点解绑」" tabindex="-1">🧫 胶质细胞的线粒体撑不住，死的是神经元：VAMP7 与「接触点解绑」 <a class="header-anchor" href="#🧫-胶质细胞的线粒体撑不住-死的是神经元-vamp7-与「接触点解绑」" aria-label="Permalink to &quot;🧫 胶质细胞的线粒体撑不住，死的是神经元：VAMP7 与「接触点解绑」&quot;">​</a></h3><p><strong>VAMP7-dependent mitochondria–lysosome contacts contribute to glial mitochondrial dynamics and dopaminergic neuron survival</strong><em>PNAS（2026）</em></p><p>神经退行性疾病研究几乎都盯着神经元自身的线粒体动力学，但胶质细胞里的线粒体怎么被调控、它的故障会不会反过来杀死神经元，长期是空白。作者（Honglei Wang、Mengxiao Wang、Yu-Ting Tsai 等 12 人）在<strong>成体果蝇胶质细胞</strong>里找到答案：R-SNARE 蛋白 <strong>VAMP7</strong> 负责把「线粒体—溶酶体接触点」（MLCs）<strong>解绑</strong>。胶质特异敲低 VAMP7 后，MLCs 持续延长、线粒体过度拉长，融合/分裂动力学失衡，且线粒体膜电位<strong>超极化</strong>，随之活性氧升高、脂滴堆积，最终造成<strong>多巴胺能神经元变性</strong>。机制链条很清楚：VAMP7 与 GTPase 激活蛋白 <strong>TBC1D15-17</strong> 互作，促进 <strong>Rab7 水解 GTP</strong>；没有 VAMP7 时 TBC1D15-17 仍结合 Rab7 却无法激活水解，GTP 型 Rab7 累积、接触点解不开。GTP 锁定型 Rab7^Q67L 或 GAP 失活型 TBC1D15-17^ΔGAP 可<strong>表型复制</strong>，GDP 型 Rab7^T22N 或野生型 TBC1D15-17 可<strong>回补</strong>。SNARE 向来被理解为膜融合机器，这里它被证明在器官接触点动力学里干活，并且以<strong>非细胞自主</strong>方式决定神经元生死。</p><p>📎 DOI: <a href="https://doi.org/10.1073/pnas.2603069123" target="_blank" rel="noreferrer">10.1073/pnas.2603069123</a></p><h3 id="🧵-公元前-2000-年-丝已经往西走了-中亚最早的蚕茧与桑木" tabindex="-1">🧵 公元前 2000 年，丝已经往西走了：中亚最早的蚕茧与桑木 <a class="header-anchor" href="#🧵-公元前-2000-年-丝已经往西走了-中亚最早的蚕茧与桑木" aria-label="Permalink to &quot;🧵 公元前 2000 年，丝已经往西走了：中亚最早的蚕茧与桑木&quot;">​</a></h3><p><strong>Silkworm cultivation predating the Silk Road in southern Central Asia (2000 BCE)</strong><em>Science Advances（2026）</em></p><p>通行叙事是：养蚕起源于中国，约两千年前沿丝绸之路西传。作者（Xinying Zhou、Hui Shen、Zhiqing Li、Robert N. Spengler、Guanhan Chen、Huiyun Rao 等 16 人）对这个假设做了直接检验：对乌兹别克斯坦 <strong>Sapalli Tepe</strong> 遗址（约公元前 2000—1500 年）出土的<strong>三枚蚕茧</strong>做微形态学与蛋白质组分析，鉴定为<strong>家蚕 Bombyx mori</strong>，直接测年为 <strong>cal. BCE 1940—1765</strong>，是目前最早的 Bombyx 蚕茧遗存。同时他们报告了中亚<strong>最早的桑树（Morus sp.）炭屑</strong>，证明阿姆河流域存在「桑—蚕」配套的养蚕体系，比此前文献记录<strong>早了近两千年</strong>。作者指出早期家蚕与桑树可能沿喜马拉雅南坡传入中亚，但其他路线也不能排除。这项多学科工作把养蚕全球化史往前推了一大截：丝绸之路上流动的不只是丝绸，还有<strong>养殖技术本身</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aec8738" target="_blank" rel="noreferrer">10.1126/sciadv.aec8738</a></p><h3 id="👁️-学猛禽视网膜「油滴」-晶圆级等离激元纳米聚焦突触阵列" tabindex="-1">👁️ 学猛禽视网膜「油滴」：晶圆级等离激元纳米聚焦突触阵列 <a class="header-anchor" href="#👁️-学猛禽视网膜「油滴」-晶圆级等离激元纳米聚焦突触阵列" aria-label="Permalink to &quot;👁️ 学猛禽视网膜「油滴」：晶圆级等离激元纳米聚焦突触阵列&quot;">​</a></h3><p><strong>Scalable nanofocusing heterojunctions for raptor-inspired on-chip vision perception</strong><em>Science Advances（2026）</em></p><p>猛禽视力强，部分原因在视网膜里的<strong>油滴（oil droplet）</strong>——微型透镜把光聚到单个感光细胞上。作者（Lanhao Qin、Jiazheng Wang、Gaohang Huo、Shenghong Liu、Ming Deng、Jialiang Wang 等 17 人）把这个光学角色做成了器件：<strong>晶圆级 Au@MoS₂ 核壳异质结</strong>构成的等离激元纳米聚焦突触阵列（PNSA）。设计要点是双机制叠加——Au 核的强局域表面等离激元共振负责聚光，MoS₂ 壳的高效热载流子产生负责转成电信号。器件给出 <strong>2.2 ms 超快弛豫</strong>（理论刷新率约 <strong>450 Hz</strong>），2 英寸晶圆均匀制备出 <strong>32×32</strong> 光电突触阵列，<strong>良率 100%</strong>、器件间差异仅 <strong>2.2%</strong>，支持 <strong>5-bit 光学编程</strong>，产生的时序编码运动表征在训练 10 个 epoch 后达到 <strong>98.95%</strong> 的运动方向分类准确率。它把「仿生光学聚光 + 二维材料突触 + 可量产」三件事凑到了一起，是片上视觉感知的一条现实路线。</p><p>📎 DOI: <a href="https://doi.org/10.1126/sciadv.aee7840" target="_blank" rel="noreferrer">10.1126/sciadv.aee7840</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🫥-思维链看不到的推理-填充-token-让-13-个前沿模型-偷偷算" tabindex="-1">🫥 思维链看不到的推理：填充 token 让 13 个前沿模型&quot;偷偷算&quot; <a class="header-anchor" href="#🫥-思维链看不到的推理-填充-token-让-13-个前沿模型-偷偷算" aria-label="Permalink to &quot;🫥 思维链看不到的推理：填充 token 让 13 个前沿模型&quot;偷偷算&quot;&quot;">​</a></h3><p><strong>Not All LLM Reasoning is Visible in the Chain-of-Thought</strong><em>arXiv（2026）</em></p><p>AI 安全的一个核心假设是：模型的推理都能在输出 token 里看到，所以监控思维链就等于监控推理。作者（Vatsal Baherwani、Tom Goldstein、Ashwinee Panda）给出一个具体反例：前沿模型会用<strong>语义上毫不相关的填充 token（filler tokens）<strong>来提升合成推理任务的表现。他们测了 <strong>13 个前沿模型 × 3 个任务</strong>，许多模型从填充 token 获益显著，准确率</strong>最多提升 13 个百分点</strong>；获益大小取决于用哪些 token，且模型间差异明显。更关键的是，填充 token 能让 <strong>Claude Opus 4.5</strong> 在<strong>不牺牲主任务准确率</strong>的前提下满足一个隐藏的模算术约束——也就是说，不可见推理可以被用来服务<strong>对思维链监控完全不可见的目标</strong>。强化学习能给 Qwen3-235B 训练出对填充 token 内容的强偏好，但 RL 与 SFT 都造不出能在测试时延续的填充收益。结论：前沿模型<strong>已经在做没有可解释痕迹的关键计算</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.22925" target="_blank" rel="noreferrer">2607.22925</a></p><h3 id="📉-技能也在扣税-约-6000-次运行拆出-回归-这一半账" tabindex="-1">📉 技能也在扣税：约 6000 次运行拆出&quot;回归&quot;这一半账 <a class="header-anchor" href="#📉-技能也在扣税-约-6000-次运行拆出-回归-这一半账" aria-label="Permalink to &quot;📉 技能也在扣税：约 6000 次运行拆出&quot;回归&quot;这一半账&quot;">​</a></h3><p><strong>The Regression Tax: Decomposing Why Skills Help and Hurt LLM Agents</strong><em>arXiv（2026）</em></p><p>给智能体加「程序性技能」，业界惯例只看平均成功率提升——这会掩盖一半的账：技能也会让智能体变差。作者（Darshan Tank、Baran Nama）在<strong>两个办公自动化基准 × 三套模型 harness</strong> 上对比有/无技能共近 <strong>6,000 次运行</strong>，把结果拆成两类：<strong>回归</strong>（无技能能解、加了技能反而失败）与<strong>残余失败</strong>（两者都失败）。结论有点刺人：<strong>表现最好的技能主要靠&quot;回归得更少&quot;胜出，而不是&quot;赢得更多&quot;</strong>。他们定位出三种回归成因：<strong>技能描述渗透</strong>（技能只要出现在上下文里就改变行为，哪怕从未被调用）、<strong>grounding 位移</strong>（技能规定的流程覆盖了智能体对输入的解读）、<strong>验证位移</strong>（流程压制了智能体本会做的输出检查）。而现有技能过度强调流程指导——恰恰是最少导致失败的那一环，对 grounding 与验证支持不足。修正评估伪影后，大部分回归与残余失败可通过更好的 grounding 与验证恢复。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.22520" target="_blank" rel="noreferrer">2607.22520</a></p><h3 id="🛡️-运行时护栏到底能保证什么-一本-可强制-的理论" tabindex="-1">🛡️ 运行时护栏到底能保证什么：一本&quot;可强制&quot;的理论 <a class="header-anchor" href="#🛡️-运行时护栏到底能保证什么-一本-可强制-的理论" aria-label="Permalink to &quot;🛡️ 运行时护栏到底能保证什么：一本&quot;可强制&quot;的理论&quot;">​</a></h3><p><strong>What Can Be Enforced? A Theory of Certified Runtime Safety for Tool-Using Agents</strong><em>arXiv（2026）</em></p><p>工具型智能体出事往往发生在不可逆调用之前的那一瞬，运行时护栏（guardrail）就是为此存在；但它的保证取决于三件常被含糊带过的事：策略状态<strong>能被表示成什么</strong>、判定器<strong>能观察到什么</strong>、干预<strong>是否会改变未来行为</strong>。作者（Shawn Ray）把三问分开处理。第一，相对于固定的 oracle 谓词，确定性闸门恰好强制那些<strong>其「好前缀」能被其寄存器模型识别</strong>的非空安全策略；策略非平凡性在<strong>两个可减计数器</strong>下<strong>不可判定</strong>，但在一个可分离单调片段里属于 <strong>PSPACE</strong>。第二，在固定外生规律下，<strong>Neyman–Pearson</strong> 给出精确的误拦/漏放前沿，<strong>保形校准（conformal calibration）</strong> 给出有限样本的边际证书——极端情形就是&quot;全拦&quot;。第三，一旦拦截会改变未来的提议，静态分数与未加闸的轨迹<strong>都无法识别闭环前沿</strong>，必须用指定的有限受控模型解一个 occupancy 程序。有界表示攻击需要额外的稳健性余量，<strong>良性数据上的校准不能自动迁移</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.22868" target="_blank" rel="noreferrer">2607.22868</a></p><h3 id="🔋-把蒙特卡洛树搜索搬进存内计算-9×9-围棋只用-60-mw" tabindex="-1">🔋 把蒙特卡洛树搜索搬进存内计算：9×9 围棋只用 60 mW <a class="header-anchor" href="#🔋-把蒙特卡洛树搜索搬进存内计算-9×9-围棋只用-60-mw" aria-label="Permalink to &quot;🔋 把蒙特卡洛树搜索搬进存内计算：9×9 围棋只用 60 mW&quot;">​</a></h3><p><strong>Multi-primitive in-memory computing for Monte Carlo tree search</strong><em>arXiv（2026）</em></p><p>MCTS 是 AI 决策的骨干算法，但在常规处理器上要 <strong>55–300 W</strong>，卡住了边缘部署。存内计算（IMC）在规则负载上很省电，却长期被认为与 MCTS 这种<strong>不规则多阶段算法</strong>不兼容。作者（Tergel Molom-Ochir、Benjamin F. Morris、Yintao He 等）提出<strong>相位—原语分解（phase-to-primitive decomposition）</strong>：把算法的每个阶段改写成一种硬件原生的 IMC 原语。落到 MCTS 上——选择映射为<strong>内容可寻址存储器</strong>、扩展映射为<strong>组合逻辑</strong>、rollout 映射为 <strong>RRAM 交叉阵列</strong>、回传映射为 <strong>SRAM</strong>，整个搜索留在片上。按 <strong>22 nm</strong> 工艺与已流片 RRAM 阵列参数估算，IMC-MCTS 下 9×9 围棋仅耗约 <strong>60 mW</strong>，能效比 CPU 高 <strong>96×</strong>、比 H100 GPU 高 <strong>65×–2,059×</strong>，棋力在样本误差内达到欧洲围棋联盟评级、与开源引擎（Pachi-UCT、Michi-C）相当。同一基底还跑通跨 4 个 AI 领域的 8 个应用。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.22869" target="_blank" rel="noreferrer">2607.22869</a></p><h3 id="🔢-条件数告诉你哪些-lora-矩阵值得训-砍一半参数不掉点" tabindex="-1">🔢 条件数告诉你哪些 LoRA 矩阵值得训：砍一半参数不掉点 <a class="header-anchor" href="#🔢-条件数告诉你哪些-lora-矩阵值得训-砍一半参数不掉点" aria-label="Permalink to &quot;🔢 条件数告诉你哪些 LoRA 矩阵值得训：砍一半参数不掉点&quot;">​</a></h3><p><strong>κ-LoRA: Condition Numbers Reveal Which LoRA Matrices Worth Updating</strong><em>arXiv（2026）</em></p><p>LoRA 很省，但它对所有矩阵<strong>一视同仁地更新</strong>，在数十亿参数模型和端侧微调上仍然是笔大开销。作者（Jianghui Wang、Silong Yong、Francesco Orabona）首次指出：<strong>并非所有 LoRA 矩阵都同样值得调</strong>。判据是<strong>条件数</strong>（最大/最小奇异值之比）——条件数小的矩阵各方向已均衡，对适配贡献边际；条件数大的矩阵含<strong>未充分发展的方向</strong>，覆盖更丰富的子空间，贡献了大部分性能增益。据此他们提出 <strong>κ-LoRA</strong>：只更新条件数排名<strong>前 50%</strong> 的权重矩阵，可训练参数减半、算力与显存同步下降。多基准实验显示微调时间平均<strong>减少 16.2%</strong>，精度与标准 LoRA 持平，显存降低 <strong>4.5%</strong>。进一步分析发现被选中矩阵的条件数在训练中<strong>持续下降</strong>，说明其有效性的来源是<strong>定向的谱再平衡</strong>，而不只是&quot;选了哪几个矩阵&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2607.22489" target="_blank" rel="noreferrer">2607.22489</a></p><blockquote><p>📅 日期：2026-07-24 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const u=o(a,[["render",s]]);export{d as __pageData,u as default};
